const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n),day=s=>ShiftMath.date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
document.querySelectorAll('input[type="number"]').forEach(el=>{el.step='any';el.required=true});
document.querySelector('.result').setAttribute('aria-live','polite');
const numeric=['rate','tax','night','weekend','other','threshold','multiplier','travel','lodging','fixed','daily','target'];
let nextId=3,base={},lastResult=null;
const today=new Date(),localDate=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
$('start').value=ShiftMath.week(localDate,1);
let shifts=[4,5,6].map((offset,id)=>({id,date:ShiftMath.add($('start').value,offset),hours:12,night:0}));
const banner=document.createElement('p');banner.className='hint';banner.textContent='Example numbers are filled in. Replace them with your own rates, hours, and costs.';document.querySelector('.intro').append(banner);
function parameters(){const p=Object.fromEntries(numeric.map(id=>[id,Number($(id).value)]));return {...p,weekstart:Number($('weekstart').value),diffOT:$('diffOT').checked}}
function bounds(){return ShiftMath.period($('start').value,$('period').value)}
function renderShifts(){const b=bounds();$('shifts').innerHTML=shifts.map(s=>`<div class="shift" data-id="${s.id}"><label>Date<input aria-label="Shift date" type="date" data-field="date" min="${b.first}" max="${b.last}" value="${s.date}" required></label><label>Paid hours<input aria-label="Paid hours" type="number" data-field="hours" min="0.25" max="24" step="0.25" value="${s.hours}" required></label><label>Night hours<input aria-label="Night hours" type="number" data-field="night" min="0" max="${s.hours}" step="0.25" value="${s.night}" required></label><button class="remove" aria-label="Remove shift on ${s.date}" data-remove="${s.id}">×</button></div>`).join('')}
function renderWeeks(){const b=bounds(),start=Number($('weekstart').value);let keys=[];for(let k=ShiftMath.week(b.first,start);k<=b.last;k=ShiftMath.add(k,7))keys.push(k);$('weeks').innerHTML='<p class="hint">Already scheduled hours per workweek · before these pickups</p>'+keys.map(k=>`<label class="week-row">${day(k)} – ${day(ShiftMath.add(k,6))}<input aria-label="Already scheduled hours for week of ${day(k)}" type="number" data-week="${k}" min="0" max="168" step="0.25" value="${base[k]??0}" required></label>`).join('');$('periodLabel').textContent=day(b.first)+' – '+day(b.last)+' · Overtime resets every '+$('weekstart').selectedOptions[0].textContent;}
function text(id,t){$(id).textContent=t}
function update(){const invalid=[...document.querySelectorAll('input')].some(el=>!el.checkValidity()||(el.type==='number'&&el.value===''));if(invalid){lastResult=null;text('headline','Check your entries');text('subtitle','Use valid numbers and shift dates inside the selected pay period.');for(const id of ['net','gross','withholding','costs','coverage','count','goal'])text(id,'—');$('progress').style.width='0%';$('breakdown').textContent='Fix the highlighted fields to see an estimate.';return}const p=parameters(),r=ShiftMath.calculate(p,shifts,base);lastResult=r;text('headline',!r.rows.length?'Add your first shift':r.breakEven?`${r.breakEven} shift${r.breakEven===1?'':'s'} to break even`:'Not covered yet');text('subtitle',!r.rows.length?'Choose pickup dates to see when the trip pays for itself.':r.breakEven?'Your planned pickups cover the trip costs at this point.':`Your current plan is ${money(Math.max(0,-r.net))} short. Add another shift to compare.`);const available=r.gross-r.withholding;const coverage=r.costs?Math.max(0,available/r.costs*100):r.rows.length?100:0;$('progress').style.width=Math.min(100,coverage)+'%';text('coverage',Math.round(coverage)+'%');text('net',money(r.net));text('count',`${r.rows.length} pickup shifts · ${r.rows.reduce((n,s)=>n+s.hours,0)} paid hours · ${r.ot} OT hours`);text('gross',money(r.gross));text('withholding','−'+money(r.withholding));text('costs','−'+money(r.costs));text('goal',r.targetAt?`✓ Your ${money(p.target)} target is reached after ${r.targetAt} planned shift${r.targetAt===1?'':'s'}.`:`${money(Math.max(0,p.target-r.net))} more needed to reach your ${money(p.target)} target. Add dated shifts to find the count.`);$('breakdown').innerHTML=r.rows.length?r.rows.map((s,i)=>`<div class="break-row"><div>${i+1}. ${day(s.date)}${s.weekend?' · Weekend':''}<small>${s.hours} hr${s.night?' · '+s.night+' night':''}${s.overtime?' · '+s.overtime+' OT':''}</small><small>${money(s.net)} cumulative after costs</small></div><strong>${money(s.pay)}<small>gross pay</small></strong></div>`).join(''):'<p class="hint">Your pickup shifts will appear here.</p>'}
base[ShiftMath.week(shifts[0].date,1)]=24;renderShifts();renderWeeks();update();
document.querySelector('.forms').addEventListener('input',e=>{const t=e.target;if(t.dataset.field){const s=shifts.find(s=>s.id===Number(t.closest('.shift').dataset.id));s[t.dataset.field]=t.dataset.field==='date'?t.value:Number(t.value);if(t.dataset.field==='hours')t.closest('.shift').querySelector('[data-field="night"]').max=t.value}else if(t.dataset.week){base[t.dataset.week]=Number(t.value)}if(['start','period','weekstart'].includes(t.id)){if(!$('start').value)return;renderWeeks();const b=bounds();document.querySelectorAll('[data-field="date"]').forEach(el=>{el.min=b.first;el.max=b.last})}update()});
$('shifts').addEventListener('click',e=>{const button=e.target.closest('[data-remove]');if(!button)return;shifts=shifts.filter(s=>s.id!==Number(button.dataset.remove));renderShifts();update()});
$('add').addEventListener('click',()=>{const b=bounds(),last=shifts.at(-1),candidate=last?ShiftMath.add(last.date||b.first,1):b.first;shifts.push({id:nextId++,date:candidate>b.last?b.last:candidate<b.first?b.first:candidate,hours:12,night:0});renderShifts();update()});
const note=document.createElement('p');note.className='hint';note.textContent='For mixed day/night hours, night differential is spread proportionally across regular and OT hours. Break-even uses the entered shifts in date order; per-shift costs are incurred as each shift is worked.';document.querySelector('aside').append(note);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_shift_estimate',title:'Read pickup shift estimate',description:'Read the currently visible pickup earnings, travel costs, and break-even estimate.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('No parameters are accepted');if(!lastResult)throw new Error('Correct invalid form entries first');return JSON.parse(JSON.stringify(lastResult))}})).catch(()=>{})}catch{}}
